"""
DataCapture Pro — Launcher / Self-Repair
=========================================
This tiny program is what the user runs. It sits next to DataCapturePro.exe
inside dist/DataCapturePro/.

Fast path:  if the _internal folder is intact, it just launches the real
            DataCapturePro.exe and exits (adds ~0.2s).

Repair path: if _internal is missing or corrupt (e.g. the user copied only the
            exe), it shows an "Installing dependencies" window, sets up a local
            Python runtime with all required packages, writes the app source
            (carried embedded in this launcher), and runs the app from that —
            fully restoring functionality without the _internal folder.
"""
import os
import sys
import subprocess
import threading
import base64
import zlib
from pathlib import Path

# ── App source is embedded here at build time (base64 of zlib-compressed py) ──
APP_SOURCE_B64 = ""

# For a PyInstaller onefile exe, sys.executable is the REAL path to the exe on
# disk (sys.argv[0] can be relative, and __file__/_MEIPASS point to the temp
# extraction dir). Using the wrong one makes the launcher look for _internal in
# the temp folder and wrongly trigger repair every time.
if getattr(sys, "frozen", False):
    HERE = Path(sys.executable).resolve().parent
else:
    HERE = Path(__file__).resolve().parent

MAIN_EXE      = HERE / "DataCapturePro.exe"
INTERNAL_DIR  = HERE / "_internal"
REPAIR_DIR    = HERE / "runtime"           # where we build a local python runtime
REPAIR_MARKER = REPAIR_DIR / ".dcp_ready"
APP_PY        = REPAIR_DIR / "capture_app.py"


def internal_ok():
    """True if the PyInstaller _internal folder looks intact."""
    if not INTERNAL_DIR.is_dir():
        return False
    # PyInstaller always drops base_library.zip and a python3xx.dll in _internal
    has_base = (INTERNAL_DIR / "base_library.zip").exists()
    has_py = any(INTERNAL_DIR.glob("python3*.dll"))
    return has_base and has_py


def launch_main():
    """Launch the real bundled exe and exit."""
    try:
        flags = 0x08000000 if os.name == "nt" else 0  # CREATE_NO_WINDOW
        subprocess.Popen([str(MAIN_EXE)], cwd=str(HERE), creationflags=flags)
        return True
    except Exception:
        return False


def write_app_source():
    REPAIR_DIR.mkdir(parents=True, exist_ok=True)
    raw = zlib.decompress(base64.b64decode(APP_SOURCE_B64))
    APP_PY.write_bytes(raw)


def find_system_python():
    """Look for an existing Python we can reuse."""
    import shutil
    for cand in ("python", "py"):
        exe = shutil.which(cand)
        if exe:
            try:
                cf = 0x08000000 if os.name == "nt" else 0  # CREATE_NO_WINDOW
                r = subprocess.run([exe, "--version"], capture_output=True,
                                   timeout=10, creationflags=cf)
                if r.returncode == 0:
                    return exe
            except Exception:
                pass
    # Common install dirs
    for base in (os.environ.get("LocalAppData", ""),
                 os.environ.get("ProgramFiles", ""), "C:\\"):
        if not base:
            continue
        for ver in ("Python312", "Python311", "Python310"):
            for sub in (f"Programs\\Python\\{ver}\\python.exe",
                        f"{ver}\\python.exe"):
                p = Path(base) / sub
                if p.exists():
                    return str(p)
    return None


# ════════════════════════════════════════════════════════════════════════════
#  Repair UI  (uses only tkinter, which ships with the OS Python we install)
# ════════════════════════════════════════════════════════════════════════════
def run_repair():
    import tkinter as tk

    root = tk.Tk()
    root.title("DataCapture Pro — Setup")
    root.configure(bg="#0d0d18")
    root.geometry("460x240")
    root.resizable(False, False)
    try:
        root.eval('tk::PlaceWindow . center')
    except Exception:
        pass

    tk.Label(root, text="Installing dependencies",
             bg="#0d0d18", fg="#e2e2f0",
             font=("Segoe UI", 15, "bold")).pack(pady=(28, 4))
    tk.Label(root, text="First-time setup — this runs once and needs internet.",
             bg="#0d0d18", fg="#8888a8",
             font=("Segoe UI", 9)).pack()

    status = tk.StringVar(value="Preparing...")
    tk.Label(root, textvariable=status, bg="#0d0d18", fg="#6c7bff",
             font=("Segoe UI", 9), wraplength=420,
             justify="center").pack(pady=(18, 6))

    # Indeterminate progress bar
    bar_wrap = tk.Frame(root, bg="#1a1a28", width=400, height=8)
    bar_wrap.pack(pady=4)
    bar_wrap.pack_propagate(False)
    bar = tk.Frame(bar_wrap, bg="#6c7bff", width=80, height=8)
    bar.place(x=0, y=0)

    state = {"x": 0, "dir": 1, "done": False, "ok": False, "err": ""}

    def animate():
        if state["done"]:
            return
        state["x"] += state["dir"] * 6
        if state["x"] > 320:
            state["dir"] = -1
        elif state["x"] < 0:
            state["dir"] = 1
        bar.place(x=state["x"], y=0)
        root.after(16, animate)

    def set_status(msg):
        try:
            root.after(0, lambda: status.set(msg))
        except Exception:
            pass

    def worker():
        try:
            set_status("Locating Python...")
            py = find_system_python()

            if not py:
                set_status("Downloading Python (one-time)...")
                py = install_python(set_status)
                if not py:
                    state["err"] = ("Could not install Python automatically.\n"
                                    "Please reinstall DataCapture Pro.")
                    state["done"] = True
                    return

            set_status("Writing application files...")
            write_app_source()

            set_status("Installing packages (this can take a few minutes)...")
            ok = install_packages(py, set_status)
            if not ok:
                state["err"] = "Failed to install required packages."
                state["done"] = True
                return

            REPAIR_MARKER.write_text("ok")
            state["ok"] = True
            state["done"] = True
        except Exception as e:
            state["err"] = str(e)
            state["done"] = True

    def check_done():
        if state["done"]:
            root.destroy()
            return
        root.after(120, check_done)

    animate()
    threading.Thread(target=worker, daemon=True).start()
    check_done()
    root.mainloop()

    if state["ok"]:
        launch_repaired(find_system_python())
    else:
        show_error(state["err"] or "Setup failed.")


def install_python(set_status):
    """Download and silently install Python, return path to python.exe."""
    import urllib.request
    ver = "3.11.9"
    url = f"https://www.python.org/ftp/python/{ver}/python-{ver}-amd64.exe"
    dst = Path(os.environ.get("TEMP", ".")) / "dcp_python_setup.exe"
    try:
        set_status("Downloading Python 3.11...")
        urllib.request.urlretrieve(url, str(dst))
    except Exception:
        return None
    try:
        set_status("Installing Python (a UAC prompt may appear)...")
        subprocess.run([str(dst), "/quiet", "InstallAllUsers=0",
                        "PrependPath=1", "Include_launcher=1", "Include_test=0"],
                       timeout=600)
    except Exception:
        return None
    finally:
        try: dst.unlink()
        except Exception: pass
    return find_system_python()


def install_packages(py, set_status):
    """Install all runtime packages into the found Python."""
    def run(args):
        try:
            si = None
            if os.name == "nt":
                si = subprocess.STARTUPINFO()
                si.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            return subprocess.run([py, "-m", "pip"] + args,
                                  capture_output=True, timeout=1800,
                                  startupinfo=si).returncode == 0
        except Exception:
            return False

    run(["install", "--upgrade", "pip", "--quiet"])

    base = ["mss", "pillow", "pynput", "opencv-python", "numpy"]
    for i, pkg in enumerate(base, 1):
        set_status(f"Installing {pkg}  ({i}/{len(base)})...")
        if not run(["install", pkg, "--quiet", "--disable-pip-version-check"]):
            return False

    # ONNX GPU runtime (DirectML works on any GPU)
    set_status("Installing GPU AI runtime (DirectML)...")
    run(["uninstall", "-y", "onnxruntime", "onnxruntime-gpu",
         "onnxruntime-directml"])
    if not run(["install", "--force-reinstall", "--no-deps",
                "onnxruntime-directml", "--quiet"]):
        run(["install", "onnxruntime", "--quiet"])
    run(["install", "flatbuffers", "protobuf", "packaging", "--quiet"])

    # Torch + ultralytics are optional (only for .pt models) — best effort
    set_status("Installing PyTorch + ultralytics (optional, .pt models)...")
    run(["install", "torch", "torchvision", "--quiet",
         "--disable-pip-version-check"])
    run(["install", "ultralytics", "--quiet", "--disable-pip-version-check"])
    return True


def launch_repaired(py):
    """Run the app from source using the repaired runtime."""
    if not py:
        show_error("Python runtime not found after setup.")
        return
    try:
        # pythonw.exe = no console window
        pyw = str(Path(py).with_name("pythonw.exe"))
        exe = pyw if Path(pyw).exists() else py
        flags = 0x08000000 if os.name == "nt" else 0  # CREATE_NO_WINDOW
        subprocess.Popen([exe, str(APP_PY)], cwd=str(REPAIR_DIR),
                         creationflags=flags)
    except Exception as e:
        show_error(f"Could not start the app: {e}")


def show_error(msg):
    try:
        import tkinter as tk
        from tkinter import messagebox
        r = tk.Tk(); r.withdraw()
        messagebox.showerror("DataCapture Pro — Setup", msg)
        r.destroy()
    except Exception:
        print("ERROR:", msg)


def main():
    # Fast path: intact bundle → just launch it
    if internal_ok() and MAIN_EXE.exists():
        if launch_main():
            return

    # Already repaired once? run from the repaired runtime
    if REPAIR_MARKER.exists() and APP_PY.exists():
        py = find_system_python()
        if py:
            launch_repaired(py)
            return

    # Need repair
    run_repair()


if __name__ == "__main__":
    try:
        main()
    except Exception:
        import traceback
        tb = traceback.format_exc()
        try:
            (HERE / "DataCapturePro_launcher_error.log").write_text(tb, encoding="utf-8")
        except Exception:
            pass
        try:
            import tkinter as _tk
            from tkinter import messagebox as _mb
            r = _tk.Tk(); r.withdraw()
            _mb.showerror("DataCapture Pro — Launcher",
                          "The launcher hit an error.\n\n" +
                          (tb.strip().splitlines()[-1] if tb.strip() else "") +
                          "\n\nA log was saved next to the app.")
            r.destroy()
        except Exception:
            pass
